document.addEventListener('click', (e) => {
  const enlace = e.target.closest('a[data-ruta]');
  if (!enlace) return;
  e.preventDefault();                       // evita la recarga
  history.pushState({}, '', enlace.href);  // cambia la URL
  pintar(location.pathname);
});

window.addEventListener('popstate', () => pintar(location.pathname));

