function Catalogo() {
  const [productos, setProductos] = useState([]);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    fetch('/api/productos')
      .then((r) => r.json())
      .then(setProductos)
      .finally(() => setCargando(false));
  }, []);

  if (cargando) return <TarjetasEsqueleto cantidad={3} />;
  return productos.map((p) => <Tarjeta key={p.id} producto={p} />);
}

